const records = $input.all().map(item => item.json);

// 1. Eksik veya geçersiz audit kayıtlarını çıkar
const validRecords = records.filter(r =>
  r.pipeline_id &&
  r.commit_id &&
  r.spec_path &&
  r.document_type &&
  r.kb_url &&
  r.target_version &&
  r.status
);

// 2. Her doküman + commit + versiyon için
// en güncel audit kaydını belirle
const latestByDocument = new Map();

for (const record of validRecords) {
  const key = JSON.stringify([
    record.pipeline_id,
    record.commit_id,
    record.spec_path,
    record.document_type,
    record.kb_url,
    record.target_version
  ]);

  const existing = latestByDocument.get(key);

  const recordTime = Date.parse(
    record.processed_at ||
    record.updatedAt ||
    record.createdAt ||
    ''
  ) || 0;

  const existingTime = existing
    ? (Date.parse(
        existing.processed_at ||
        existing.updatedAt ||
        existing.createdAt ||
        ''
      ) || 0)
    : -1;

  if (
    !existing ||
    recordTime > existingTime ||
    (recordTime === existingTime &&
      Number(record.id || 0) > Number(existing.id || 0))
  ) {
    latestByDocument.set(key, record);
  }
}

// 3. Sadece recovery gerektiren kayıtları seç
const recoveryStatuses = new Set([
  'FAILED',
  'TIMEOUT',
  'PENDING_REVIEW'
]);

const candidates = [...latestByDocument.values()]
  .filter(r =>
    recoveryStatuses.has(
      String(r.status).trim().toUpperCase()
    )
  );

// 4. Sonuçları sonraki node'lara aktar
return candidates.map(record => ({
  json: {
    ...record,
    original_status: String(record.status).toUpperCase(),
    recovery_action: 'VERIFY_KB',
    recovery_required: true
  }
}));

const response = $json;
const source = $('Loop Over Items').item.json;

const documents = Array.isArray(response.body)
  ? response.body
  : Array.isArray(response.body?.documents)
    ? response.body.documents
    : [];

// spec_name yerine gerçek dosya adını kullan
const expectedName = String(source.spec_path || '')
  .split('/')
  .pop()
  .replace(/\.md$/i, '')
  .trim()
  .toLowerCase();

const matches = documents.filter(doc =>
  String(doc.doc_name || '')
    .trim()
    .toLowerCase() === expectedName
);

let verificationStatus;

if (response.statusCode !== 200) {
  verificationStatus = 'CHECK_FAILED';
} else if (matches.length === 1) {
  verificationStatus = 'FOUND_IN_KB';
} else if (matches.length > 1) {
  verificationStatus = 'AMBIGUOUS';
} else {
  verificationStatus = 'NOT_FOUND';
}

const existingDoc =
  verificationStatus === 'FOUND_IN_KB'
    ? matches[0]
    : null;

return {
  json: {
    ...source,
    verification_status: verificationStatus,
    found_in_kb: Boolean(existingDoc),
    existing_doc_id: existingDoc?.doc_id || '',
    existing_doc_md5: existingDoc?.md5 || '',
    existing_doc_path: existingDoc?.path || '',
    matching_documents: matches.length,
    http_status: response.statusCode
  }
};

const response = $json;
const source = $('Verify KB Document').item.json;

const jobs = Array.isArray(response.body?.jobs)
  ? response.body.jobs
  : [];

const expectedFile = source.spec_path
  .split('/')
  .pop()
  .toLowerCase();

const matchingJobs = jobs.filter(job =>
  String(job.file_name || '').toLowerCase() === expectedFile &&
  String(job.version || '') === String(source.target_version)
);

const completedJobs = matchingJobs.filter(job =>
  String(job.status || '').toLowerCase() === 'done' &&
  Boolean(job.doc_id)
);

const activeJobs = matchingJobs.filter(job =>
  ['pending', 'queued', 'running', 'processing', 'in_progress']
    .includes(String(job.status || '').toLowerCase())
);

let recoveryDecision = 'MANUAL_REVIEW';
let recoveredDocId = '';

if (response.statusCode !== 200) {
  recoveryDecision = 'JOB_CHECK_FAILED';
} else if (activeJobs.length > 0) {
  recoveryDecision = 'WAIT_FOR_JOB';
} else if (completedJobs.length > 0) {
  const ids = [...new Set(completedJobs.map(job => job.doc_id))];

  if (ids.length === 1) {
    recoveryDecision = 'VERIFY_COMPLETED_DOC';
    recoveredDocId = ids[0];
  } else {
    recoveryDecision = 'MANUAL_REVIEW';
  }
} else if (matchingJobs.length === 0) {
  recoveryDecision = 'JOB_NOT_FOUND';
} else {
  recoveryDecision = 'MANUAL_REVIEW';
}

return {
  json: {
    ...source,
    matching_job_count: matchingJobs.length,
    completed_job_count: completedJobs.length,
    active_job_count: activeJobs.length,
    recovered_doc_id: recoveredDocId,
    recovery_decision: recoveryDecision
  }
};

const crypto = require('crypto');

const response = $json;
const githubFile = response.body ?? response;

const source = $('Verify KB Document').item.json;

if (githubFile.encoding !== 'base64' || !githubFile.content) {
  throw new Error('GitHub dosya içeriği Base64 formatında değil.');
}

// GitHub Base64 içeriğini gerçek byte'lara dönüştür
const fileBuffer = Buffer.from(
  githubFile.content.replace(/\s/g, ''),
  'base64'
);

// MD5 hesapla
const sourceMd5 = crypto
  .createHash('md5')
  .update(fileBuffer)
  .digest('hex');

const kbMd5 = String(source.existing_doc_md5 || '')
  .toLowerCase();

const md5Matches = sourceMd5 === kbMd5;

return {
  json: {
    ...source,
    github_blob_sha: githubFile.sha,
    github_file_size: fileBuffer.length,
    source_md5: sourceMd5,
    kb_md5: kbMd5,
    md5_matches: md5Matches,
    recovery_decision: md5Matches
      ? 'ALREADY_INDEXED'
      : 'CONTENT_MISMATCH'
  }
};

const response = $json;
const source = $('Evaluate Recovery Jobs').item.json;

const documents = Array.isArray(response.body)
  ? response.body
  : [];

const expectedName = String(source.spec_path || '')
  .split('/')
  .pop()
  .replace(/\.md$/i, '')
  .toLowerCase();

const matches = documents.filter(doc =>
  String(doc.doc_name || '').toLowerCase() === expectedName &&
  String(doc.doc_id || doc.id || '') ===
    String(source.recovered_doc_id || '')
);

const verified =
  response.statusCode === 200 &&
  matches.length === 1 &&
  Boolean(matches[0]?.md5);

const doc = verified ? matches[0] : null;

return {
  json: {
    ...source,
    verification_status: verified
      ? 'FOUND_IN_KB'
      : 'NOT_VERIFIED',
    found_in_kb: verified,
    existing_doc_id: doc?.doc_id || '',
    existing_doc_md5: doc?.md5 || '',
    existing_doc_path: doc?.path || '',
    matching_documents: matches.length,
    http_status: response.statusCode
  }
};

const crypto = require('crypto');

const response = $json;
const githubFile = response.body ?? response;

const source = $('Verify Rechecked Document').item.json;

if (githubFile.encoding !== 'base64' || !githubFile.content) {
