const record = $json;

const requiredFields = [
  'pipeline_id',
  'commit_id',
  'spec_path',
  'spec_name',
  'document_type',
  'kb_url',
  'target_version',
  'status'
];

const missingFields = requiredFields.filter(field =>
  record[field] === undefined ||
  record[field] === null ||
  String(record[field]).trim() === ''
);

if (missingFields.length > 0) {
  throw new Error(
    'Missing required audit fields: ' +
    missingFields.join(', ')
  );
}

// Yalnızca spec_kb_audit tablosundaki sütunları döndür
return {
  json: {
    pipeline_id: record.pipeline_id,
    commit_id: record.commit_id,
    spec_path: record.spec_path,
    spec_name: record.spec_name,
    document_type: record.document_type,
    kb_url: record.kb_url,
    target_version: record.target_version,
    doc_id: String(record.doc_id ?? '').replace(/^['"]+|['"]+$/g, '').trim(),
    status: String(record.status).toUpperCase(),
    error_message: record.error_message || '',
    processed_at: new Date().toISOString()
  }
};

const history = $input.all().map(item => item.json);

const runIndex = $runIndex;
const newRecord = $('Normalize Recovery Audit')
  .all(0, runIndex)[0]?.json;

if (!newRecord) {
  throw new Error(`New record missing at run ${runIndex}`);
}

const norm = value =>
  String(value ?? '')
    .replace(/^['"]+|['"]+$/g, '')
    .trim();

const matchingHistory = history.filter(r =>
  norm(r.pipeline_id) === norm(newRecord.pipeline_id) &&
  norm(r.commit_id) === norm(newRecord.commit_id) &&
  norm(r.spec_path) === norm(newRecord.spec_path) &&
  norm(r.target_version) === norm(newRecord.target_version)
);

const duplicate = matchingHistory.find(r =>
  norm(r.status).toUpperCase() ===
    norm(newRecord.status).toUpperCase() &&
  norm(r.doc_id) === norm(newRecord.doc_id) &&
  norm(r.error_message) === norm(newRecord.error_message)
);

return [{
  json: {
    ...newRecord,
    should_save: !duplicate,
    audit_action: duplicate ? 'SKIP_DUPLICATE' : 'INSERT',
    previous_audit_id: duplicate?.id ?? null,

    // Geçici debug alanları
    debug_run_index: runIndex,
    debug_new_spec: newRecord.spec_path,
    debug_new_commit: newRecord.commit_id,
    debug_history_count: history.length,
    debug_matching_count: matchingHistory.length,
    debug_history_specs: [...new Set(history.map(r => r.spec_path))],
    debug_history_commits: [...new Set(history.map(r => r.commit_id))],
    debug_existing_statuses: matchingHistory.map(r => ({
      id: r.id,
      status: r.status,
      doc_id: r.doc_id,
      error_message: r.error_message
    }))
  }
}];

const rows = $input.all()
  .map(item => item.json)
  .filter(r =>
    r.pipeline_id &&
    r.commit_id &&
    r.spec_path &&
    r.target_version
  );

const groups = new Map();

for (const row of rows) {
  const key = JSON.stringify([
    row.pipeline_id,
    row.commit_id,
    row.spec_path,
    row.target_version
  ]);

  if (!groups.has(key)) groups.set(key, []);
  groups.get(key).push(row);
}

const duplicates = [];

for (const [key, records] of groups.entries()) {
  records.sort((a, b) =>
    Number(a.id || 0) - Number(b.id || 0)
  );

  for (let i = 1; i < records.length; i++) {
    const previous = records[i - 1];
    const current = records[i];

    const same =
      String(previous.status || '') === String(current.status || '') &&
      String(previous.doc_id || '') === String(current.doc_id || '') &&
      String(previous.error_message || '') ===
        String(current.error_message || '');

    if (same) {
      duplicates.push({
        spec_path: current.spec_path,
        previous_id: previous.id,
        duplicate_id: current.id,
        status: current.status
      });
    }
  }
}

return [{
  json: {
    total_rows: $input.all().length,
    valid_rows: rows.length,
    duplicate_count: duplicates.length,
    duplicates
  }
}];
